function E({registerIndicator:x,nulls:N}){x({id:"oa-sak",name:"SAK: Swiss Army Knife Indicator",category:"Filters",placement:"pane",inputs:[{key:"filterType",type:"select",label:"Filter Type",default:"BP",options:[{label:"EMA",value:"EMA"},{label:"SMA",value:"SMA"},{label:"Gauss",value:"Gauss"},{label:"Butter",value:"Butter"},{label:"Smooth",value:"Smooth"},{label:"HP",value:"HP"},{label:"2PHP",value:"2PHP"},{label:"BP",value:"BP"},{label:"BS",value:"BS"}]},{key:"period",type:"number",label:"Period",default:20,min:2,max:5e3,step:1},{key:"n",type:"number",label:"SMA Length (N)",default:10,min:1,max:5e3,step:1,tooltip:"Only used for SMA mode"},{key:"delta",type:"number",label:"Delta (BW)",default:.1,min:.01,max:10,step:.01,tooltip:"Bandwidth for BP/BS modes"}],plots:[{key:"sak",type:"line",title:"SAK",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",dashed:!0}],calc(p,m){const h=Math.max(2,Math.floor(Number(m.period)||20)),M=Math.max(1,Math.floor(Number(m.n)||10)),H=Math.max(.01,Number(m.delta)||.1),l=["EMA","SMA","Gauss","Butter","Smooth","HP","2PHP","BP","BS"].includes(m.filterType)?m.filterType:"BP",S=new Array(p.length).fill(NaN),d=p.map(e=>e.close),b=2*Math.PI,k=(e,f)=>Number.isFinite(f)&&Math.abs(f)>1e-12?e/f:NaN;let t=0,u=0,P=0;if(l==="BP"||l==="BS")P=k(1,Math.cos(b*H/h)),u=Math.cos(b/h),t=P-Math.sqrt(Math.max(0,P*P-1));else if(l==="Gauss"||l==="Butter"||l==="2PHP")u=2.415*(1-Math.cos(b/h)),t=-u+Math.sqrt(Math.max(0,u*u+2*u));else{const e=Math.cos(b/h);t=k(e+Math.sin(b/h)-1,e)}let s=1,y=0,o=1,i=0,n=0,a=0,r=0;if(l==="EMA"?(s=1,o=t,i=0,n=0,a=1-t,r=0):l==="SMA"?(s=1,y=1/M,o=1/M,i=0,n=0,a=1,r=0):l==="Gauss"?(s=t*t,o=1,i=0,n=0,a=2*(1-t),r=-(1-t)*(1-t)):l==="Butter"?(s=t*t/4,o=1,i=2,n=1,a=2*(1-t),r=-(1-t)*(1-t)):l==="Smooth"?(s=t*t/4,o=1,i=2,n=1,a=0,r=0):l==="HP"?(s=1-t/2,o=1,i=-1,n=0,a=1-t,r=0):l==="2PHP"?(s=(1-t/2)*(1-t/2),o=1,i=-2,n=1,a=2*(1-t),r=-(1-t)*(1-t)):l==="BP"?(s=(1-t)/2,o=1,i=0,n=-1,a=u*(1+t),r=-t):l==="BS"&&(s=(1+t)/2,o=1,i=-2*u,n=1,a=u*(1+t),r=-t),[s,y,o,i,n,a,r].some(e=>!Number.isFinite(e)))return{sak:N(S)};const B=e=>Number.isFinite(e)?e:0,c=new Array(p.length).fill(0);for(let e=0;e<p.length;e++){const f=B(d[e]),v=e>=1?c[e-1]:0;if(l==="SMA"){const A=e>=M?B(d[e-M]):0;c[e]=y*f+a*v-y*A}else{const A=e>=1?B(d[e-1]):0,F=e>=2?B(d[e-2]):0,w=e>=2?c[e-2]:0;c[e]=s*(o*f+i*A+n*F)+a*v+r*w}S[e]=Number.isFinite(c[e])?c[e]:NaN,Number.isFinite(c[e])||(c[e]=0)}return{sak:N(S)}}})}export{E as default};
